/**
 * The page outside the shell: sign-in, sign-up, a setup step, a status (`design/archetypes/auth-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/auth-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  PageTransition,
  Ref,
  SlotOutlet,
  SlotTemplate,
  classes,
  derived,
  elementRef,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/auth-page.module.css'
import transitions from '@polymorph/recipes/conventions/page-transitions.module.css'
import { Card } from '../structure/Card'

/** The page outside the shell: sign-in, sign-up, a setup step, a status: the inputs it takes, by the React member's prop names. */
export interface AuthPageProps {
  /**
   * The layout, where `illustrated` is the public account layout with host-supplied artwork.
   */
  layout?: 'centered' | 'illustrated'
  pending?: boolean
  /**
   * The `<h1>`.
   */
  title: string
  transitionKey?: string
}

/** The page outside the shell: sign-in, sign-up, a setup step, a status. */
@Component({
  selector: 'pm-auth-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [PageTransition, Ref, SlotOutlet, SlotTemplate, Card],
  // prettier-ignore
  template: `<ng-template pmSlot="backAction" [pmSlotOf]="$"><ng-content select="[slot=backAction]" /></ng-template>
<ng-template pmSlot="brand" [pmSlotOf]="$"><ng-content select="[slot=brand]" /></ng-template>
<ng-template pmSlot="cardFooter" [pmSlotOf]="$"><ng-content select="[slot=cardFooter]" /></ng-template>
<ng-template pmSlot="description" [pmSlotOf]="$"><ng-content select="[slot=description]" /></ng-template>
<ng-template pmSlot="footer" [pmSlotOf]="$"><ng-content select="[slot=footer]" /></ng-template>
<ng-template pmSlot="illustration" [pmSlotOf]="$"><ng-content select="[slot=illustration]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- page -->
<main
[attr.class]="e1()"
[attr.aria-busy]="e2()"
[attr.data-auth-layout]="e3()"
data-member="auth-page"
>@if (e4()) {<!-- topbar -->
<div
[attr.class]="e5()"
><ng-container [pmSlotOutlet]="'brand'" [pmSlotOf]="$" /></div>}
<!-- body -->
<div
[attr.class]="e6()"
[pmRef]="body"
><!-- column -->
<div
pmPageTransition
[transitionKey]="e7()"
[pending]="e8()"
[ribbon]="e9()"
[attr.class]="e10()"
>@if (e11()) {<!-- illustration -->
<div
[attr.class]="e12()"
aria-hidden="true"
><ng-container [pmSlotOutlet]="'illustration'" [pmSlotOf]="$" /></div>}
<!-- formColumn -->
<div
[attr.class]="e13()"
>@if (e14()) {<!-- brand -->
<div
[attr.class]="e15()"
><ng-container [pmSlotOutlet]="'brand'" [pmSlotOf]="$" /></div>}
@if (e16()) {<!-- frame -->
<div
[attr.class]="e17()"
><!-- card -->
<div
[attr.class]="e18()"
><!-- heading -->
<div
[attr.class]="e19()"
[attr.data-auth-enter]="e20()"
><!-- titleRow -->
<div
[attr.class]="e21()"
>@if (e22()) {<!-- backAction -->
<div
[attr.class]="e23()"
><ng-container [pmSlotOutlet]="'backAction'" [pmSlotOf]="$" /></div>}
<!-- title -->
<h1
[attr.class]="e24()"
>{{ e25() }}</h1></div>
@if (e26()) {<!-- description -->
<p
[attr.class]="e27()"
><ng-container [pmSlotOutlet]="'description'" [pmSlotOf]="$" /></p>}</div>
<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />
@if (e28()) {<!-- cardFooter -->
<div
[attr.class]="e29()"
><ng-container [pmSlotOutlet]="'cardFooter'" [pmSlotOf]="$" /></div>}</div></div>} @else {<pm-card><!-- card -->
<div
[attr.class]="e30()"
><!-- heading -->
<div
[attr.class]="e31()"
[attr.data-auth-enter]="e32()"
><!-- titleRow -->
<div
[attr.class]="e33()"
>@if (e34()) {<!-- backAction -->
<div
[attr.class]="e35()"
><ng-container [pmSlotOutlet]="'backAction'" [pmSlotOf]="$" pmSlotInto="default" /></div>}
<!-- title -->
<h1
[attr.class]="e36()"
>{{ e37() }}</h1></div>
@if (e38()) {<!-- description -->
<p
[attr.class]="e39()"
><ng-container [pmSlotOutlet]="'description'" [pmSlotOf]="$" pmSlotInto="default" /></p>}</div>
<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" pmSlotInto="default" />
@if (e40()) {<!-- cardFooter -->
<div
[attr.class]="e41()"
><ng-container [pmSlotOutlet]="'cardFooter'" [pmSlotOf]="$" pmSlotInto="default" /></div>}</div></pm-card>}
@if (e42()) {<!-- footer -->
<div
[attr.class]="e43()"
><ng-container [pmSlotOutlet]="'footer'" [pmSlotOf]="$" /></div>}</div></div></div></main>`,
})
export class AuthPage {
  /**
   * The layout, where `illustrated` is the public account layout with host-supplied artwork.
   */
  readonly layout = input<Exclude<AuthPageProps['layout'], undefined>, AuthPageProps['layout']>(
    'centered',
    { transform: (value: AuthPageProps['layout']) => (value === undefined ? 'centered' : value) },
  )
  readonly pending = input<Exclude<AuthPageProps['pending'], undefined>, AuthPageProps['pending']>(
    false,
    { transform: (value: AuthPageProps['pending']) => (value === undefined ? false : value) },
  )
  /**
   * The `<h1>`.
   */
  readonly title = input.required<AuthPageProps['title']>()
  readonly transitionKey = input<AuthPageProps['transitionKey']>(undefined)
  protected readonly $ = useMember({
    events: [],
    props: {
      layout: () => this.layout(),
      pending: () => this.pending(),
      title: () => this.title(),
      transitionKey: () => this.transitionKey(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly body = elementRef<HTMLElement>()
  protected readonly illustrated = derived(() => this.$p.layout === 'illustrated')

  constructor() {
    watchEffect(
      () => [this.illustrated.value, this.$p.transitionKey],
      () => this.effect1(),
      true,
    )
  }

  protected e1() {
    return classes(styles.page, this.illustrated.value ? styles.illustrated : undefined)
  }

  protected e2() {
    return this.$p.pending ? true : undefined
  }

  protected e3() {
    return this.$p.layout
  }

  protected e4() {
    return this.illustrated.value && this.$.filled('brand')
  }

  protected e5() {
    if (!(this.illustrated.value && this.$.filled('brand'))) return undefined as never
    return styles.topbar
  }

  protected e6() {
    return styles.body
  }

  protected e7() {
    return this.$p.transitionKey
  }

  protected e8() {
    return this.$p.pending
  }

  protected e9() {
    return transitions.indicator
  }

  protected e10() {
    return classes(
      styles.column,
      this.$p.transitionKey !== undefined ? transitions.page : undefined,
    )
  }

  protected e11() {
    return this.illustrated.value && this.$.filled('illustration')
  }

  protected e12() {
    if (!(this.illustrated.value && this.$.filled('illustration'))) return undefined as never
    return styles.illustration
  }

  protected e13() {
    return styles.formColumn
  }

  protected e14() {
    return !this.illustrated.value && this.$.filled('brand')
  }

  protected e15() {
    if (!(!this.illustrated.value && this.$.filled('brand'))) return undefined as never
    return styles.brand
  }

  protected e16() {
    return this.illustrated.value
  }

  protected e17() {
    if (!this.illustrated.value) return undefined as never
    return styles.frame
  }

  protected e18() {
    if (!this.illustrated.value) return undefined as never
    return styles.card
  }

  protected e19() {
    if (!this.illustrated.value) return undefined as never
    return styles.heading
  }

  protected e20() {
    if (!this.illustrated.value) return undefined as never
    return ''
  }

  protected e21() {
    if (!this.illustrated.value) return undefined as never
    return classes(styles.titleRow, this.$.filled('backAction') ? styles.withBack : undefined)
  }

  protected e22() {
    if (!this.illustrated.value) return undefined as never
    return this.$.filled('backAction')
  }

  protected e23() {
    if (!this.illustrated.value) return undefined as never
    if (!this.$.filled('backAction')) return undefined as never
    return styles.backAction
  }

  protected e24() {
    if (!this.illustrated.value) return undefined as never
    return styles.title
  }

  protected e25() {
    if (!this.illustrated.value) return undefined as never
    return this.$p.title
  }

  protected e26() {
    if (!this.illustrated.value) return undefined as never
    return this.$.filled('description')
  }

  protected e27() {
    if (!this.illustrated.value) return undefined as never
    if (!this.$.filled('description')) return undefined as never
    return styles.description
  }

  protected e28() {
    if (!this.illustrated.value) return undefined as never
    return this.$.filled('cardFooter')
  }

  protected e29() {
    if (!this.illustrated.value) return undefined as never
    if (!this.$.filled('cardFooter')) return undefined as never
    return styles.cardFooter
  }

  protected e30() {
    if (this.illustrated.value) return undefined as never
    return styles.card
  }

  protected e31() {
    if (this.illustrated.value) return undefined as never
    return styles.heading
  }

  protected e32() {
    if (this.illustrated.value) return undefined as never
    return ''
  }

  protected e33() {
    if (this.illustrated.value) return undefined as never
    return classes(styles.titleRow, this.$.filled('backAction') ? styles.withBack : undefined)
  }

  protected e34() {
    if (this.illustrated.value) return undefined as never
    return this.$.filled('backAction')
  }

  protected e35() {
    if (this.illustrated.value) return undefined as never
    if (!this.$.filled('backAction')) return undefined as never
    return styles.backAction
  }

  protected e36() {
    if (this.illustrated.value) return undefined as never
    return styles.title
  }

  protected e37() {
    if (this.illustrated.value) return undefined as never
    return this.$p.title
  }

  protected e38() {
    if (this.illustrated.value) return undefined as never
    return this.$.filled('description')
  }

  protected e39() {
    if (this.illustrated.value) return undefined as never
    if (!this.$.filled('description')) return undefined as never
    return styles.description
  }

  protected e40() {
    if (this.illustrated.value) return undefined as never
    return this.$.filled('cardFooter')
  }

  protected e41() {
    if (this.illustrated.value) return undefined as never
    if (!this.$.filled('cardFooter')) return undefined as never
    return styles.cardFooter
  }

  protected e42() {
    return this.$.filled('footer')
  }

  protected e43() {
    if (!this.$.filled('footer')) return undefined as never
    return styles.footer
  }

  private effect1(): void {
    void (
      this.illustrated.value &&
      this.body.value
        ?.querySelectorAll('[data-auth-enter]')
        .forEach((item, index) =>
          (item as HTMLElement).style.setProperty(
            '--pm-page-enter-order',
            String(Math.min(index, 9)),
          ),
        )
    )
  }
}
